from fractions import Fraction as F
prior = {1: F(1, 2), 2: F(1, 6), 3: F(1, 3)}
white = {1: F(1, 3), 2: F(2, 3), 3: F(3, 6)}      # P(white | box) = white / total
joint = {b: prior[b] * white[b] for b in prior}
pw = sum(joint.values())
post = {b: joint[b] / pw for b in prior}
print('P(W) =', pw, '| joints =', joint)
print('P(Box-2 | W) =', post[2], '=', round(float(post[2]), 2), '| posteriors sum to', sum(post.values()))
import random; random.seed(0); N = 10**6; w = w2 = 0
for _ in range(N):
    b = random.choices((1, 2, 3), weights=(3, 1, 2))[0]
    if random.random() < white[b]:
        w += 1; w2 += (b == 2)
print('simulation estimate:', round(w2 / w, 4))
